import { MeshBasicNodeMaterial } from 'three/webgpu';
import { mix, smoothstep, uv, vec3 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, DoubleSide } = ctx.THREE;
  const root = new Group();
  const resources = [];
  const timelines = [];
  const primitiveResults = [];
  let cleaned = false;

  const cardWidth = 2.5;
  const cardHeight = 1.5625;

  const gradientMaterial = new MeshBasicNodeMaterial({
    side: DoubleSide,
    transparent: false,
  });

  const gradientT = smoothstep(0.0, 1.0, uv().y);
  gradientMaterial.colorNode = mix(
    vec3(0.043, 0.043, 0.063),
    mix(
      vec3(0.086, 0.086, 0.114),
      vec3(0.91, 0.925, 0.949),
      smoothstep(0.68, 1.0, gradientT)
    ),
    gradientT
  );

  const gradientGeometry = new PlaneGeometry(cardWidth + 0.08, cardHeight + 0.08);
  const gradientPlane = new Mesh(gradientGeometry, gradientMaterial);
  gradientPlane.position.z = -0.035;
  root.add(gradientPlane);
  resources.push(gradientGeometry, gradientMaterial);

  const imageMaterial = new MeshBasicNodeMaterial({
    color: 0xffffff,
    side: DoubleSide,
    transparent: false,
  });

  const imageGeometry = new PlaneGeometry(cardWidth, cardHeight);
  const imagePlane = new Mesh(imageGeometry, imageMaterial);
  imagePlane.position.z = 0;
  root.add(imagePlane);
  resources.push(imageGeometry, imageMaterial);

  const accentMaterial = new MeshBasicNodeMaterial({
    color: '#ff2a38',
    side: DoubleSide,
  });

  const accentGeometry = new PlaneGeometry(0.026, cardHeight + 0.02);
  const accentPlane = new Mesh(accentGeometry, accentMaterial);
  accentPlane.position.set(-cardWidth * 0.5 - 0.035, 0, 0.012);
  root.add(accentPlane);
  resources.push(accentGeometry, accentMaterial);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      if (cleaned) {
        texture.dispose?.();
        return;
      }

      texture.colorSpace = ctx.THREE.SRGBColorSpace;
      imageMaterial.map = texture;
      imageMaterial.needsUpdate = true;
      resources.push(texture);
    }).catch(() => {});
  }

  for (const primitive of config.cinematicPrimitives ?? []) {
    const handler = ctx.primitives?.[primitive.name];
    if (typeof handler === 'function') {
      const result = handler(root, primitive.params);
      if (result) {
        primitiveResults.push(result);
        if (result.timeline) timelines.push(result.timeline);
      }
    }
  }

  const entrance = gsap.fromTo(
    root.scale,
    { x: 0.985, y: 0.985, z: 0.985 },
    {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.7,
      ease: 'power3.out',
      paused: true,
    }
  );
  timelines.push(entrance);
  entrance.play();

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    if (cleaned) return;
    cleaned = true;

    for (const timeline of timelines) {
      timeline?.kill?.();
    }

    for (const result of primitiveResults) {
      result?.cleanup?.();
    }

    for (const resource of resources) {
      resource?.dispose?.();
    }

    root.traverse((object) => {
      object.userData = object.userData || {};
      object.userData.handlers = {};
    });
  };

  return root;
}
